"Путь, км":"Distance, km",
"Источники":"Wellsprings",
"Редкие духи":"Rare spirits",
"Необычные духи":"Uncommon spirits",
"Обычные духи":"Common spirits",
"Европа":"Europe",
"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"The old roads of Nav, Olympus, Asgard and the hills of the sidhe meet here — from Moscow to Dublin.",
"Азия":"Asia",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"From the Ural Mountains to the Pacific. The celestial dragons of China come from here, and Siberia and Central Asia are lands of Slavic spirits.",
"Африка":"Africa",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"Here, by the Nile, stand the gates of the Duat — home of the Egyptian gods and desert spirits.",
"Северная Америка":"North America",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"Land of the feathered serpents: the Aztec gods and spirits came out of the Valley of Mexico.",
"Южная Америка":"South America",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"Jungle, the Andes and the Amazon. Aztec spirits scattered all the way here — right down to Tierra del Fuego.",
"Австралия и Океания":"Australia and Oceania",
"Своих мифологий у Ордена здесь пока нет: все духи Австралии и Океании — гости, которых занесла Перепутица.":"The Order has no native mythologies here yet: every spirit in Australia and Oceania is a guest blown in by the Great Tangle.",
"Антарктида":"Antarctica",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"Only penguins and ice spirits here. The Gates don’t open this way — it’s too cold even for Catchers.",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"There have always been many spirit worlds — every people has its own: Nav for the Slavs, the realm of Hades for the Greeks, Asgard for the Norse, the fairy mounds for the Celts, the Duat for the Egyptians, the Heavens for the Chinese, Mictlan for the Aztecs. They were held in place by <b>Alatyr</b>, the burning white stone at the center of all worlds. Every gate led to its own land, and spirits never mixed up their roads.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — кто куда. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"One autumn night Koschei the Deathless decided to hide his death somewhere safer — right in the heart of Alatyr. The stone cracked and split apart. Every gate flew open at once, the roads between worlds tangled into a ball, and the spirits and gods of seven mythologies spilled into our world, every which way. That night became known as <b>the Great Tangle</b>. Koschei insists the stone cracked on its own, but for some reason Loki and Sun Wukong giggle whenever he says so.",
"Теперь Гиппокамп плещется в московском фонтане, Леший гуляет по токийскому парку, а Ниссе греет котов в подъездах Каира. Любого духа можно встретить в любом уголке земли. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища там, где осели: Капище по соседству с Пагодой, Храм через улицу от Пирамиды. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"Now a Hippocamp splashes in a Moscow fountain, a Leshy strolls through a Tokyo park, and a Nisse warms cats in Cairo stairwells. Any spirit can be met in any corner of the earth. Rifts — cracks left by the broken stone — open in every city, and the gods build their shrines wherever they have settled: a Kapishche next door to a Pagoda, a Temple across the street from a Pyramid. The city also gives birth to its own new spirits: Vayfayka, Tramvaynik, Fonarnik.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"The first to get along with the newcomers weren't scientists but grandmothers with their charms: it turned out a charm made with care calms any spirit, wherever it comes from. That is how the <b>Order of the Charm</b> was born — a union of Catchers from every land. Your task: find spirits, catch them with charms, draw power from wellsprings, close rifts and collect Alatyr shards. Who knows — maybe one day there will be enough of them to untangle the roads home.",
