"Зимние праздники: Морозко и Снегурка выходят к людям, духи Ветра и Воды встречаются чаще, в источниках — подарки.":"Winter holidays: Morozko and Snegurka come out to people, Wind and Water spirits appear more often, and wellsprings hold gifts.",
