"Сервер не подтвердил этот бой. Проверь интернет и попробуй снова.":"The server didn't confirm this battle. Check your connection and try again.",
"На карту":"To the map",
"Защитники «{0}» отступили — Капище «{1}» свободно!":"“{0}” defenders retreated — Kapishche “{1}” is free!",
"Победа засчитана, но пока шёл бой, на Капище сменились защитники.":"Win counted, but the defenders at the Kapishche changed during the battle.",
"«Достойно, Ловчий», — {0} склоняет голову. Капище «{1}» освящено тобой до конца дня.":"“Well fought, Catcher,” — {0} bows their head. Kapishche “{1}” is consecrated by you until the end of the day.",
