"жетоны обновятся через {0}":"tokens refresh in {0}",
"Команда на бой":"Battle team",
"Соперник — Ловчий с рейтингом ±{0} от твоего, а если такого нет — Ловчий Ордена. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"Your opponent is a Catcher rated within ±{0} of you, or a Catcher of the Order if there's no one. Rating depends on your opponent’s strength · XP for the first {1} battles of the day",
"Общая таблица всех Ловчих появится, когда к игре подключат облачный сервер.":"The full table of all Catchers will appear once the game is connected to the cloud server.",
"Обновляется в реальном времени":"Updates in real time",
"Ловчих":"Catchers",
"{0} {1} в сезоне":"{0} {1} this season",
"Загружаю таблицу…":"Loading table…",
"Таблица недоступна: {0}":"Table unavailable: {0}",
"В этом сезоне ещё никто не сыграл в Лиге — будь первым!":"No one has played in the League this season yet — be the first!",
"{0}-е место":"#{0}",
"Ты":"You",
"Лучшие в лиге «{0}»":"Top of the “{0}” league",
"Топ-50 сезона":"Season top 50",
"Нажми на Ловчего, чтобы открыть его карточку.":"Tap a Catcher to open their card.",
"от {0}":"from {0}",
"начало пути":"start of the path",
"Получено в этом сезоне":"Received this season",
"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"Rating depends on your opponent: beating a strong one gives a lot, a weak one little; losing to a weak one costs more. In your league a win over an equal gives +{0}, a loss −{1}; the higher the league, the slower the climb. You can drop out of a league. The league reward is given once per season. At the start of a new season, rating above {2} is cut in half, and the Order gives a chest for last season's top league. In the “{3}”, “{4}” and “{5}” leagues — an amulet too.",
"<b>{0}-е место</b> из {1} в сезоне":"<b>#{0}</b> of {1} this season",
"Сыграй бой, чтобы попасть в таблицу":"Play a battle to get on the table",
"Карточка откроется после обновления сервера":"The card will open after a server update",
"Неизвестный ход":"Unknown action",
"Слишком много ударов сразу":"Too many hits at once",
"Неизвестный приём":"Unknown move",
"Этот приём не выучен":"This move isn't learned",
"Неверный приём":"Invalid move",
"Этого духа не выпустить":"Can't send out this spirit",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"Throw the charm as the ring shrinks: “Great!” gives more XP and a better catch chance.",
"Источники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"Wellsprings refill after a few minutes — walking a loop brings in supplies.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"Your buddy walks with you and finds essence of its family.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"In the League, live Catchers fight: beating a strong opponent gives more rating than beating a weak one.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"Rifts open at Kapishches every hour: gather a team of three spirits.",
"Сияющие духи редки — их выдают искры вокруг.":"Shiny spirits are rare — the sparkles around them give them away.",
"Коконы греются шагами: одновременно можно греть три.":"Cocoons are warmed by steps: you can warm three at once.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"Move with the joystick: a slight tilt walks, all the way runs. Kilometers count for cocoons just the same.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"The World Atlas takes you to any corner of the Earth once every half hour — the Gates of the Great Tangle do it instantly.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"Daily quests refresh at midnight, and completing all three earns the Daily Chest.",
"Поставь защитника на Капище своего клана — он принесёт искры.":"Place a defender at your clan's Kapishche — it will bring sparks.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"Weather boosts spirits of its element: in the rain water spirits appear more often.",
"Привяжи вход через Google, Яндекс или Telegram — прогресс не потеряется при смене телефона.":"Link a Google, Yandex or Telegram sign-in — your progress won't be lost when you change phones.",
"Дари друзьям подарки каждый день — дружба растёт и приносит опыт.":"Give friends gifts every day — friendship grows and brings XP.",
"Лови духов Нави по всему свету":"Catch spirits of Nav all over the world",
