"Вход через {0} перейдёт к твоему текущему Ловчему, а у {1} его больше не будет.":"Sign-in with {0} will move to your current Catcher, and {1} will no longer have it.",
"У того Ловчего есть и другие способы входа — его прогресс останется доступен через них.":"That Catcher has other sign-in methods — their progress stays reachable through them.",
"<b>У того Ловчего не останется других способов входа — его прогресс станет недоступен навсегда.</b>":"<b>That Catcher will have no other way to sign in — their progress will be lost forever.</b>",
"Привязать сюда":"Link here",
"Готово: вход через {0} теперь у этого Ловчего":"Done: sign-in with {0} now belongs to this Catcher",
"Не удалось привязать — попробуй ещё раз":"Couldn’t link — try again",
"Вход уже привязан":"Sign-in already linked",
"Вход через {0} привязан к Ловчему {1}.":"The {0} sign-in is linked to Catcher {1}.",
"Можно перейти в ту учётную запись — тогда текущий гостевой прогресс на этом устройстве останется в прежней учётной записи, вернуться в неё будет нельзя. Или привязать этот вход к текущему Ловчему.":"You can switch to that account — your current guest progress on this device stays in the old account and you won’t be able to return to it. Or link this sign-in to your current Catcher.",
"Можно перейти в ту учётную запись — текущий прогресс останется в своей. Или привязать этот вход к текущему Ловчему.":"You can switch to that account — your current progress stays in its own. Or link this sign-in to your current Catcher.",
