"Там, где Алатырь дал трещину, из-под земли бьёт вода Перепутицы. У Источников Ловчие всех земель черпают обереги и припасы.":"Where the Alatyr cracked, the water of the Great Tangle springs from the ground. At Wellsprings, Catchers of every land draw charms and supplies.",
