"Как тебя зовут, Ловчий?":"What's your name, Catcher?",
"Дальше":"Next",
"Твой первый дух":"Your first spirit",
"Орден вручает тебе кокон. Он уже теплеет…":"The Order hands you a cocoon. It's already getting warm…",
"Весь мир — твой":"The whole world is yours",
"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"The Great Tangle knotted the roads of the world, and the Order of the Charm opened the Gates for Catchers: pick any corner of the Earth in the World Atlas — that’s where your hunt begins. Walk the map with the joystick, and step into new lands through the Atlas. The game doesn’t need your phone’s real location. Your progress is stored on the game server and is available only to you; the server checks every action, so you need an internet connection. Map places and weather for the chosen area are loaded from OpenStreetMap and Open-Meteo (weather can be turned off in the settings).",
